<?php namespace Workspace; $pid=(int)$project['id']; $now=time(); ?>
<p><a href="<?= h(url('project',['id'=>$pid])) ?>">← <?= h($project['title']) ?></a> · <a href="<?= h(url('github',['project'=>$pid])) ?>">Синхронизация GitHub</a> · <a href="<?= h(url('security')) ?>">MFA</a></p>
<section class="panel"><h2>Очередь review</h2><p><?php foreach(['all'=>'Все PR','pending'=>'Ожидают review','mine'=>'Мои review'] as $mode=>$label): ?><a href="<?= h(url('lead',['project'=>$pid,'mode'=>$mode])) ?>" <?= $leadMode===$mode?'aria-current="page"':'' ?>><?= h($label) ?></a> · <?php endforeach ?></p><p>Внутреннее review основного PR задачи. Наблюдение GitHub не старше 15 минут; решение не публикуется в GitHub и не заменяет QA или допуск выпуска.</p>
<?php foreach($leadTasks as $t): $r=$t['review'];$pin=$t['pin'];$current=$r&&leadSame($pin,$r);$pending=$r&&$r['state']==='pending';$eligible=array_diff_key($leadPeople,[(int)$t['assignee_id']=>true]); ?>
<article class="panel inset"><h3><a href="<?= h(url('task',['id'=>$t['id']])) ?>">#<?= (int)$t['id'] ?> <?= h($t['title']) ?></a></h3>
<p><?= $pin?'PR #'.(int)$pin['pr_number'].' · '.$pin['head_sha']:'Нет свежего открытого PR' ?></p>
<?php if($r): ?><p><?= h($r['state']) ?> · ревьюер <?= h($leadPeople[$r['reviewer_id']]??('#'.$r['reviewer_id'].' (нет прав)')) ?> · <?= $current?'актуальный SHA':'историческое / требуется синхронизация' ?> · <?= h(leadDuration((int)$r['created_at'],$now)) ?> с последнего события</p><?php endif ?>
<?php if($leadManage&&$pin&&$eligible): ?><form method="post" class="formgrid"><?php formFields('lead.review') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="task_id" value="<?= (int)$t['id'] ?>"><input type="hidden" name="previous_id" value="<?= h($r['id']??'') ?>"><input type="hidden" name="pin_hash" value="<?= h(leadPinHash($pin)) ?>"><input type="hidden" name="head_sha" value="<?= h($pin['head_sha']) ?>"><input type="hidden" name="operation" value="<?= $pending&&$current?'replace':'assign' ?>"><label>Ревьюер<select name="reviewer_id" required><?php selectOptions($eligible) ?></select></label><label>Причина<input name="note" maxlength="1000" required></label><button class="primary"><?= $pending&&$current?'Заместить':'Назначить' ?> (MFA)</button></form><?php endif ?>
<?php if($pending&&($leadManage||($current&&(int)$r['reviewer_id']===(int)$user['id']))): ?><form method="post" class="formgrid"><?php formFields('lead.review') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="task_id" value="<?= (int)$t['id'] ?>"><input type="hidden" name="previous_id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="pin_hash" value="<?= h(leadPinHash($pin)) ?>"><input type="hidden" name="head_sha" value="<?= h($pin['head_sha']??'') ?>"><label>Действие<select name="operation"><?php if($current&&(int)$r['reviewer_id']===(int)$user['id']): ?><option value="approved">Принять</option><option value="changes">Запросить изменения</option><?php endif ?><?php if($leadManage): ?><option value="cancelled">Отменить review</option><?php endif ?></select></label><label>Обоснование<input name="note" required maxlength="1000"></label><button>Сохранить (MFA)</button></form><?php endif ?>
<?php if($t['history']): ?><details><summary>История review (20 событий)</summary><?php foreach($t['history'] as $event): ?><p><?= h(gmdate('Y-m-d H:i:s',(int)$event['created_at'])) ?> UTC · <?= h($event['operation']) ?> → <?= h($event['state']) ?> · ревьюер #<?= (int)$event['reviewer_id'] ?> · исполнитель действия #<?= (int)$event['actor_id'] ?> · <code><?= h($event['head_sha']) ?></code> · <?= h($event['note']) ?></p><?php endforeach ?></details><?php endif ?></article><?php endforeach ?>
<?php if(!$leadTasks): ?><p>Нет задач со связанным PR или историей review.</p><?php endif ?><?php if($leadMore): ?><p><a href="<?= h(url('lead',['project'=>$pid,'after'=>end($leadTasks)['id'],'mode'=>$leadMode])) ?>">Следующие задачи →</a></p><?php endif ?></section>
<section class="panel"><h2>Ожидание зависимостей</h2><p>Время по отдельной зависимости, не сумма времени простоя проекта. Для зависимостей до обновления начало неизвестно; при первом указании причины фиксируется время наблюдения.</p>
<?php foreach(array_slice($leadWaits,0,100) as $w): ?><article class="panel inset"><p><a href="<?= h(url('task',['id'=>$w['task_id']])) ?>"><?= h($w['title']) ?></a> ожидает <a href="<?= h(url('task',['id'=>$w['prerequisite_id']])) ?>"><?= h($w['prerequisite_title']) ?></a> · срок <?= h($w['due_on']??'—') ?></p><p><?= $w['id']===null?'Начало неизвестно':(($w['observed_only']?'Не менее ':'').h(leadDuration((int)$w['started_at'],$now))) ?> · <?= h(($w['reason']??'')!==''?$w['reason']:'Причина не указана') ?></p>
<?php if($leadManage): ?><form method="post" class="inline"><?php formFields('lead.wait') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="task_id" value="<?= (int)$w['task_id'] ?>"><input type="hidden" name="prerequisite_id" value="<?= (int)$w['prerequisite_id'] ?>"><input type="hidden" name="wait_id" value="<?= h($w['id']??'') ?>"><input type="hidden" name="version" value="<?= h($w['version']??'') ?>"><label>Причина задержки<input name="reason" maxlength="1000" required value="<?= h($w['reason']??'') ?>"></label><button>Сохранить (MFA)</button></form><?php endif ?></article><?php endforeach ?>
<?php if(count($leadWaits)>100): ?><p>Показаны первые 100 активных зависимостей по приоритету.</p><?php endif ?><?php if(!$leadWaits): ?><p>Нет незавершённых зависимостей.</p><?php endif ?>
<h3>Завершённые интервалы (100 последних)</h3><?php foreach($leadWaitHistory as $w): ?><p>Задача #<?= (int)$w['task_id'] ?> · зависимость #<?= (int)$w['prerequisite_id'] ?> · <?= $w['observed_only']?'не менее ':'' ?><?= h(leadDuration((int)$w['started_at'],(int)$w['ended_at'])) ?> · <?= h($w['end_reason']) ?> · <?= h($w['reason']) ?></p><?php endforeach ?></section>
<section class="panel"><h2>Технические решения (ADR)</h2><?php if($leadManage): ?><form method="post" class="formgrid"><?php formFields('lead.decision') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="state" value="open"><label>Название<input name="title" maxlength="180" required></label><label>ID задачи (необязательно)<input name="task_id" type="number" min="1"></label><label>Контекст и альтернативы<textarea name="context" maxlength="4000" required></textarea></label><label>Предлагаемое решение и последствия<textarea name="resolution" maxlength="4000" required></textarea></label><button class="primary">Открыть решение (MFA)</button></form><?php endif ?>
<?php foreach($leadDecisions as $d): ?><article class="panel inset"><h3>#<?= (int)($d['previous_id']??$d['id']) ?> <?= h($d['title']) ?> · <?= h($d['state']) ?></h3><?php if($d['task_id']): ?><p><a href="<?= h(url('task',['id'=>$d['task_id']])) ?>">Задача #<?= (int)$d['task_id'] ?></a></p><?php endif ?><p>Контекст</p><pre class="release-text"><?= h($d['context']) ?></pre><p>Решение</p><pre class="release-text"><?= h($d['resolution']) ?></pre><?php if($d['original_actor']!==null): ?><p>Автор #<?= (int)$d['original_actor'] ?> · <?= h(gmdate('Y-m-d H:i:s',(int)$d['original_at'])) ?> UTC</p><?php endif ?><p>Сотрудник #<?= (int)$d['actor_id'] ?> · <?= h(gmdate('Y-m-d H:i:s',(int)$d['created_at'])) ?> UTC · <?= h($d['note']) ?></p>
<?php if($leadManage&&$d['state']==='open'): ?><form method="post" class="inline"><?php formFields('lead.decision') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="previous_id" value="<?= (int)$d['id'] ?>"><label>Решение<select name="state"><option value="accepted">Принять</option><option value="rejected">Отклонить</option></select></label><label>Обоснование<input name="note" required maxlength="1000"></label><button>Зафиксировать (MFA)</button></form><?php endif ?></article><?php endforeach ?><?php if(!$leadDecisions): ?><p>Нет решений.</p><?php endif ?><p>До 100 актуальных решений, открытые — в начале.</p></section>
